["UI: Расстояние до цели"] = {
["outline"] = "None",
["xOffset"] = 175,
["displayText"] = "%c",
["customText"] = "function()\n    if UnitIsUnit(\"player\", \"target\") or not UnitExists(\"target\") or not UnitIsVisible(\"target\")  then\n        return \"\"\n    end\n    \n    local targetID = UnitGUID(\"target\")\n    if not aura_env.lastCheck or aura_env.lastCheck + 0.2 < GetTime() or aura_env.lastTarget ~= targetID then\n        aura_env.lastCheck = GetTime()\n        aura_env.lastTarget = targetID\n        \n        if UnitPlayerControlled(\"target\") then\n            if UnitInParty(\"target\") then\n                local dist = UnitDistanceSquared(\"target\")\n                if dist then\n                    aura_env.value = string.format(\"%.1f\", dist ^ 0.5)\n                    return aura_env.value\n                end\n                return \"\"\n            end\n            aura_env.value = aura_env.friendlyDistance(\"target\")\n            return aura_env.value\n        end\n        \n        if UnitReaction(\"target\", \"player\") > 4 then\n            aura_env.value = aura_env.friendlyDistance(\"target\")\n            return aura_env.value\n        elseif UnitCanAttack(\"player\", \"target\") then\n            aura_env.value = aura_env.harmDistance(\"target\")\n            return aura_env.value\n        end\n        \n    end\n    return aura_env.value or \"\"\nend",
["yOffset"] = -286,
["anchorPoint"] = "CENTER",
["customTextUpdate"] = "update",
["url"] = "",
["actions"] = {
["start"] = {
},
["finish"] = {
},
["init"] = {
["custom"] = "aura_env.harmDistance = function(unit)\n    local output = \"> 100\"\n    for k, v in pairs(aura_env.HarmItems) do\n        if IsItemInRange(v.id, unit) then\n            output = v.text\n            break\n        end\n    end\n    return output\nend\naura_env.friendlyDistance = function(unit)\n    local output = \"> 80\"    \n    for k, v in pairs(aura_env.FriendItems)  do\n        if IsItemInRange(v.id, unit) then\n            output = v.text\n            break\n        end\n    end\n    \n    return output\nend\naura_env.HarmItems = {\n    {\n        id = 37727,\n        text = \"0 - 5\"\n    },\n    {\n        id = 63427,\n        text = \"5 - 6\"\n    },\n    {\n        id = 34368,\n        text = \"6 - 8\"\n    },\n    {\n        id = 32321,\n        text = \"8 - 10\"\n    },\n    {\n        id = 33069,\n        text = \"10 - 15\"\n    },\n    {\n        id = 10645,\n        text = \"15 - 20\"\n    },\n    {\n        id = 31463,\n        text = \"20 - 25\"\n    },\n    {\n        id = 34191,\n        text = \"25 - 30\"\n    },\n    {\n        id = 24269,\n        text = \"30 - 35\"\n    },\n    {\n        id = 28767,\n        text = \"35 - 40\"\n    },\n    {\n        id = 23836,\n        text = \"40 - 45\"\n    },\n    {\n        id = 116139,\n        text = \"45 - 50\"\n    },\n    {\n        id = 32825,\n        text = \"50 - 60\"\n    },\n    {\n        id = 41265,\n        text = \"60 - 70\"\n    },\n    {\n        id = 35278,\n        text = \"70 - 80\"\n    },\n    {\n        id = 33119,\n        text = \"80 - 100\"\n    },\n}\n\naura_env.FriendItems  = {\n    {\n        id = 37727,\n        text = \"< 5\"\n    },\n    {\n        id = 63427,\n        text = \"5 - 6\"\n    },\n    {\n        id = 33278,\n        text = \"6 - 8\"\n    },\n    {\n        id = 32321, \n        text = \"8 - 10\"\n    },\n    {\n        id = 34722,\n        text = \"10 - 15\"\n    },\n    {\n        id = 21519,\n        text = \"15 - 20\"\n    },\n    {\n        id = 31463,\n        text = \"20 - 25\"\n    },\n    {\n        id = 34191,\n        text = \"25 - 30\"\n    },\n    {\n        id = 18904,\n        text = \"30 - 35\"\n    },\n    {\n        id = 34471,\n        text = \"35 - 40\"\n    },\n    {\n        id = 32698,\n        text = \"40 - 45\"\n    },\n    {\n        id = 116139,\n        text = \"45 - 50\"\n    },\n    {\n        id = 32825,\n        text = \"50 - 60\"\n    },\n    {\n        id = 41265,\n        text = \"60 - 70\"\n    },\n    {\n        id = 35278,\n        text = \"70 - 80\"\n    },\n}\naura_env.lastTarget = \"\"",
