["finish"] = {
},
["init"] = {
["do_custom"] = true,
["custom"] = "aura_env.spellWrath = 190984\naura_env.spellStarfire = 194153\naura_env.spellNewMoon = 274281\naura_env.spellHalfMoon = 274282\naura_env.spellFullMoon = 274283\naura_env.spellStellarFlare = 202347\n\naura_env.talentWildSurges = 406890\naura_env.talentSotF = 114107\naura_env.talenMoonGuardian = 429520\n\naura_env.buffSolarEclipse = 48517\naura_env.buffLunarEclipse = 48518\n\naura_env.solarInstanceId = nil\naura_env.lunarInstanceId = nil\n\naura_env.powerCasts = {\n    [C_Spell.GetSpellInfo(aura_env.spellNewMoon)[\"name\"]] =         {10},\n    [C_Spell.GetSpellInfo(aura_env.spellHalfMoon)[\"name\"]] =        {20},\n    [C_Spell.GetSpellInfo(aura_env.spellFullMoon)[\"name\"]] =        {40},\n    [C_Spell.GetSpellInfo(aura_env.spellStarfire)[\"name\"]] =        {8},\n    [C_Spell.GetSpellInfo(aura_env.spellWrath)[\"name\"]] =           {6},\n    [C_Spell.GetSpellInfo(aura_env.spellStellarFlare)[\"name\"]] =    {12}\n}\n\naura_env.isTWWS1TierSet4pActive = false\n\nlocal ItemSetsRegistered = {\n    [\"TWW_S1\"] = {\n        [212056] = true, -- Head\n        [212054] = true, -- Shoulders\n        [212059] = true, -- Chest\n        [212055] = true, -- Legs\n        [212057] = true, -- Hands\n    }\n}\n\nlocal tierSlots = {\n    (GetInventorySlotInfo(\"ChestSlot\")),\n    (GetInventorySlotInfo(\"HeadSlot\")),\n    (GetInventorySlotInfo(\"ShoulderSlot\")),\n    (GetInventorySlotInfo(\"LegsSlot\")),\n    (GetInventorySlotInfo(\"HandsSlot\")),\n}\n\nlocal function IsSetBonusActive(tiername, bonuscount)\n    local items = ItemSetsRegistered[tiername]\n    local pieces_equipped = 0\n    for _, slot in ipairs(tierSlots) do\n        local itemId = GetInventoryItemID(\"player\", slot)\n        if items and items[itemId] then pieces_equipped = pieces_equipped + 1 end\n    end\n    return (pieces_equipped >= bonuscount)\nend\n\nlocal function GetUnitsInCombatCount()\n    local count = 0\n    for i = 1,40 do\n        local target = \"nameplate\"..i\n        local t = UnitAffectingCombat(target)\n        if UnitAffectingCombat(target) then\n            count = count + 1\n            if count >= 4 then\n                return 4\n            end\n        end\n    end\n    \n    return count\nend\n\nlocal function GetPowerFromCast()\n    local cast = UnitCastingInfo(\"player\") or nil\n    local castSpellId = select(9, UnitCastingInfo(\"player\"))\n    \n    if not cast then\n        return 0\n    end\n    \n    local data = aura_env.powerCasts[cast] or nil\n    if not data then\n        return 0\n    end\n    \n    local power = data[1] or 0\n    \n    local solarEclipseActive = WA_GetUnitBuff(\"player\", aura_env.buffSolarEclipse)\n    local lunarEclipseActive = WA_GetUnitBuff(\"player\", aura_env.buffLunarEclipse)\n    \n    -- WS talent exists\n    if IsPlayerSpell(aura_env.talentWildSurges) and (castSpellId == aura_env.spellWrath or castSpellId == aura_env.spellStarfire) then\n        power = power + 2\n    end\n    \n    -- MG talent exists\n    if IsPlayerSpell(aura_env.talenMoonGuardian) and castSpellId == aura_env.spellStarfire then\n        power = power + 2\n    end\n    \n    -- TWW_S1 4p tierset\n    if aura_env.isTWWS1TierSet4pActive then\n        if solarEclipseActive then\n            if castSpellId == aura_env.spellWrath then\n                power = power + 2\n            end\n            if castSpellId == aura_env.spellStarfire then\n                power = power + 5\n            end\n        end\n        if lunarEclipseActive then\n            if castSpellId == aura_env.spellWrath then\n                power = power + 2\n            end\n            if castSpellId == aura_env.spellStarfire then\n                power = power + 5\n            end\n        end\n    end\n    \n    -- SotF talent exists\n    if IsPlayerSpell(aura_env.talentSotF) then\n        -- Casting wrath\n        if solarEclipseActive and castSpellId == aura_env.spellWrath then\n            power = power * 1.6\n        end\n        \n        -- Casting starfire\n        if lunarEclipseActive and castSpellId == aura_env.spellStarfire then\n            local unitsInCombat = GetUnitsInCombatCount()\n            if unitsInCombat > 1 then\n                -- It should be \"unitsInCombat - 1\" but idk how blizzard counts. It looks like \"unitsInCombat - 2\" works better\n                power = power * (1 + 0.2 * (unitsInCombat - 2))\n            end\n        end\n    end\n    \n    return power\nend\n\nlocal function FloorPower(power)\n    if not power then \n        return 0\n    end\n    return math.floor(power/10)\nend\n\naura_env.getPredictionValue = function()\n    local ap = UnitPower(\"player\", SPELL_POWER_LUNAR_POWER, true) or 0\n    local powerCast = 10 * GetPowerFromCast()\n    return FloorPower(ap + powerCast)\nend\n\n\naura_env.getOverlayValue = function()\n    local ap = UnitPower(\"player\", SPELL_POWER_LUNAR_POWER, true) or 0\n    local maxAP = UnitPowerMax(\"player\" , SPELL_POWER_LUNAR_POWER, true) or 0\n    \n    local predictAP = ap + 10 * GetPowerFromCast()\n    if predictAP > maxAP then\n        predictAP = maxAP\n    end\n    \n    return FloorPower(ap), FloorPower(predictAP)\nend\n\naura_env.getDurationValue = function()\n    local ap = UnitPower(\"player\", SPELL_POWER_LUNAR_POWER) or 0\n    local maxAP = UnitPowerMax(\"player\" , SPELL_POWER_LUNAR_POWER) or 0\n    return ap, maxAP, true\nend\n\naura_env.updateAddedAuras = function(addedAuras)\n    if not addedAuras then\n        return\n    end\n    \n    for _, v in pairs(addedAuras) do\n        if v.spellId == aura_env.buffSolarEclipse then\n            aura_env.solarInstanceId = v.auraInstanceID\n        end\n        if v.spellId == aura_env.buffLunarEclipse then\n            aura_env.lunarInstanceId = v.auraInstanceID\n        end\n    end\nend\n\naura_env.auraUnitShouldTrigger = function(removedAuras)\n    if not removedAuras then\n        return false\n    end\n    \n    local shouldTrigger = false\n    for _, auraInstanceId in pairs(removedAuras) do        \n        if auraInstanceId == aura_env.solarInstanceId then\n            aura_env.solarInstanceId = nil\n            shouldTrigger = true\n        end\n        if auraInstanceId == aura_env.lunarInstanceId then\n            aura_env.lunarInstanceId = nil\n            shouldTrigger = true\n        end\n    end\n    \n    return shouldTrigger\nend\n\naura_env.updateTierSets = function()\n    aura_env.isTWWS1TierSet4pActive = IsSetBonusActive(\"TWW_S1\", 4)\nend",
},
},
