["actions"] = {
["start"] = {
},
["init"] = {
["do_custom"] = true,
["custom"] = "aura_env.spellMindBlast = 8092\n\naura_env.powerCasts = {\n    [C_Spell.GetSpellInfo(aura_env.spellMindBlast)[\"name\"]] = {6},\n}\n\nlocal function GetPowerFromCast()\n    local cast = UnitCastingInfo(\"player\") or nil\n    if not cast then\n        return 0\n    end\n\n    local data = aura_env.powerCasts[cast] or nil\n    if not data then\n        return 0\n    end\n\n    local power = data[1] or 0\n\n    return power\nend\n\naura_env.getPredictionValue = function()\n    local insanity = UnitPower(\"player\", SPELL_POWER_INSANITY, false) or 0\n    return insanity + GetPowerFromCast()\nend\n\n\naura_env.getOverlayValue = function()\n    local insanity = UnitPower(\"player\", SPELL_POWER_INSANITY, false) or 0\n    local maxInsanity = UnitPowerMax(\"player\" , SPELL_POWER_INSANITY, false) or 0\n    \n    local predictInsanity = insanity + GetPowerFromCast()\n    if predictInsanity > maxInsanity then\n        predictInsanity = maxInsanity\n    end\n    \n    return insanity, predictInsanity\nend\n\naura_env.getDurationValue = function()\n    local insanity = UnitPower(\"player\", SPELL_POWER_INSANITY) or 0\n    local maxInsanity = UnitPowerMax(\"player\" , SPELL_POWER_INSANITY) or 0\n    return insanity, maxInsanity, true\nend",
},
