["custom"] = "function(allstates, event, ...)\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID, _,_, auraType = ...\n        if subEvent == \"SPELL_CAST_SUCCESS\"\n        and spellID == 368661\n        and aura_env.timers then\n            aura_env.timers[sourceGUID] = GetTime()\n            local unit = UnitTokenFromGUID(sourceGUID)\n            if unit then \n                local exists = C_NamePlate.GetNamePlateForUnit(unit)\n                if exists then\n                    allstates:Update(sourceGUID, {\n                            progressType = \"timed\",\n                            duration = 14.5,\n                            expirationTime = 14.5 + GetTime(),\n                            unit = unit,\n                    })\n                end\n            end\n            \n        elseif subEvent == \"UNIT_DIED\" and aura_env.timers[destGUID] then\n            aura_env.timers[destGUID] = nil\n        end\n        \n        \n    elseif event == \"NAME_PLATE_UNIT_ADDED\" then\n        local unit = ...\n        local guid = UnitGUID(unit)\n        if guid and aura_env.timers and aura_env.timers[guid] then\n            local passedTime = GetTime() - aura_env.timers[guid]\n            local duration = 14.5\n            allstates:Update(guid, {\n                    progressType = \"timed\",\n                    duration = (passedTime < duration and duration-passedTime) or 0,\n                    expirationTime = (passedTime < duration and duration-passedTime + GetTime()) or 0,\n                    unit = unit,\n            })\n        end\n        \n    elseif event == \"NAME_PLATE_UNIT_REMOVED\" then\n        local unit = ...\n        allstates:Remove(UnitGUID(unit))\n    end\nend",
