["group_count"] = "0",
["custom"] = "function(allstates, event, ...)\n    if event == \"UNIT_SPELLCAST_SUCCEEDED\" and aura_env.timers then\n        local unit, _, spellID = ...\n        if spellID == 357827 then\n            local guid = UnitGUID(unit)\n            aura_env.timers[guid] = GetTime()\n            local exists = C_NamePlate.GetNamePlateForUnit(unit)\n            if exists then\n                allstates:Update(guid, {\n                        progressType = \"timed\",\n                        duration = 17,\n                        expirationTime = 17 + GetTime(),\n                        unit = unit,\n                })\n            end\n        end\n        \n    elseif event == \"NAME_PLATE_UNIT_ADDED\" then\n        local unit = ...\n        local guid = UnitGUID(unit)\n        if guid and aura_env.timers and aura_env.timers[guid] then\n            local passedTime = GetTime() - aura_env.timers[guid]\n            local duration = 17\n            allstates:Update(guid, {\n                    progressType = \"timed\",\n                    duration = (passedTime < duration and duration-passedTime) or 0,\n                    expirationTime = (passedTime < duration and duration-passedTime + GetTime()) or 0,\n                    unit = unit,\n            })\n        end\n        \n    elseif event == \"NAME_PLATE_UNIT_REMOVED\" then\n        local unit = ...\n        allstates:Remove(UnitGUID(unit))\n        \n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID = ...\n        if subEvent == \"UNIT_DIED\" and aura_env.timers[destGUID] then\n            aura_env.timers[destGUID] = nil\n        end\n    end\nend",
