["custom"] = "function(allstates, event, ...)\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ...\n        if spellID == 319724 then\n            if subEvent == \"SPELL_AURA_APPLIED\" then\n                local remaining = allstates:Get(\"\", \"remaining\")\n                allstates:Update(\"\", {\n                        remaining = remaining and remaining + 1 or 1,\n                })\n            elseif subEvent == \"SPELL_AURA_REMOVED\" then\n                local remaining = allstates:Get(\"\", \"remaining\")\n                if not remaining then return end\n                if (remaining - 1) > 0 then\n                    allstates:Update(\"\", {\n                            remaining = remaining - 1,\n                    })\n                else\n                    allstates:Remove(\"\")\n                end\n            end\n        end\n    end\nend",
