["events"] = "cleu:SPELL_CAST_SUCCESS",
["spellIds"] = {
},
["use_spellId"] = true,
["custom"] = "function(states, _, _, _, _, sourceGUID, sourceName, _, _, _, _, _, _, ...)\n    \n    if sourceName then\n        \n        local unit = UnitTokenFromGUID(sourceGUID)\n        if UnitInParty(unit) and UnitGroupRolesAssigned(unit) == \"DAMAGER\" then\n            \n            local raid = not C_PvP.IsSoloShuffle() and not C_PvP.IsRatedArena() and not C_PvP.IsSoloRBG() and UnitInRaid(\"player\")\n            local nameExists\n            \n            if aura_env.config.specificNames then\n                \n                nameExists = false\n                local names = raid and aura_env.names.raid or aura_env.names.dungeon\n                for n,_ in pairs(names) do\n                    if UnitInParty(n) and UnitGroupRolesAssigned(n) == \"DAMAGER\" then\n                        nameExists = true\n                        break\n                    end\n                end\n                \n                \n                local name = Ambiguate(sourceName, \"short\")\n                if nameExists and not names[name] then return end\n                if not nameExists and raid then return end\n            end\n            \n            if not nameExists and raid then return end\n            \n            local spellID = ...\n            if aura_env.spells[spellID] then\n                states[sourceName] = {\n                    show = true,\n                    changed = true,\n                    autoHide = true,\n                    progressType = \"timed\",\n                    duration = 5,\n                    expirationTime = GetTime() + 5,\n                    name = sourceName,\n                    unit = unit,\n                    icon = C_Spell.GetSpellTexture(spellID),\n                }\n                return true\n            end\n        end\n    end\nend",
