["custom"] = "function(allstates, event, ...)\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" and aura_env.flag then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID, _,_, auraType = ...\n        if (subEvent == \"SPELL_AURA_APPLIED\" or subEvent == \"SPELL_AURA_APPLIED_DOSE\")\n        and destGUID == WeakAuras.myGUID\n        and spellID == 1224737\n        and not WeakAuras.GetActiveTriggers(aura_env.id)[1] then\n            allstates:Update(\"\", {\n                    progressType = \"timed\",\n                    duration = 3,\n                    expirationTime = 3 + GetTime(),\n                    autoHide = true,\n            })\n        end\n    elseif event == \"UNIT_SPELLCAST_CHANNEL_STOP\" then\n        local _, _, spellID = ...\n        if spellID == 1224731 then\n            aura_env.flag = true\n        end\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.flag = false\n    end\nend",
