["init"] = {
["custom"] = "aura_env.isBoss = function(unit)\n    local isBoss = false\n    for i = 1, 8 do\n        if UnitGUID(\"boss\"..i) == UnitGUID(unit) then\n            isBoss = true\n            break\n        end\n    end\n    return isBoss\nend\n\naura_env.blacklist = {}\n\nfor _, entry in pairs(aura_env.config.blacklist) do\n    local key = entry.useSpellName and tostring(entry.spell) or tonumber(entry.spell)\n    if key then\n        aura_env.blacklist[key] = true\n    end\nend\n\n\n",
