["custom_type"] = "stateupdate",
["customVariables"] = "{\n    interruptible = {\n        display = \"Interruptible\",\n        type = \"bool\",\n    },\n    \n    sayChat = {\n        display = \"sayChat\",\n        type = \"string\",\n    },\n    spellName = {\n        display = \"spellName\",\n        type = \"string\",\n    },\n    spellID = {\n        display = \"spellID\",\n        type = \"number\",\n    },\n}",
["event"] = "Health",
["genericShowOn"] = "showOnActive",
["subeventPrefix"] = "SPELL",
["names"] = {
},
["spellIds"] = {
},
["events"] = "NAME_PLATE_UNIT_ADDED NAME_PLATE_UNIT_REMOVED UNIT_SPELLCAST_START:boss:nameplate UNIT_SPELLCAST_STOP:nameplate:boss UNIT_SPELLCAST_CHANNEL_START:nameplate:boss UNIT_SPELLCAST_CHANNEL_STOP:nameplate:boss UNIT_DELAYED_SPELL_START UNIT_TARGET:nameplate:boss CLEU:UNIT_DIED ENCOUNTER_END",
["custom"] = "function(states, e, ...)\n    \n    if e == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        if not ... then return end\n        local _,sub,_,_,_,_,_,GUID,_,_,_,spellID = ...\n        if not states[GUID..\"-boss\"] and not states[GUID..\"-nameplate\"] then return end\n        \n        if sub == \"UNIT_DIED\" then\n            if states[GUID..\"-boss\"] or states[GUID..\"-nameplate\"] then\n                local state = states[GUID..\"-boss\"] or states[GUID..\"-nameplate\"]\n                state.show = false;\n                state.changed = true;\n                return true\n            end\n        end\n        \n    elseif e == \"ENCOUNTER_END\" then\n        if not ... then return end\n        for _, v in pairs(states) do\n            if v.isBoss then\n                v.show = false;\n                v.changed = true;\n            end\n        end\n        return true\n        \n    else\n        local unit = ... \n        if not unit then return end\n        local GUID = UnitGUID(unit)\n        local isBoss = aura_env.isBoss(unit) and true or false\n        local ID = GUID and GUID..\"-\"..(isBoss and \"boss\" or \"nameplate\")\n        local koKR = _G.LOCALE_koKR\n        \n        if e == \"NAME_PLATE_UNIT_REMOVED\" or (e ==\"UNIT_SPELLCAST_STOP\" or e ==\"UNIT_SPELLCAST_CHANNEL_STOP\") \n        or (e == \"UNIT_TARGET\" and (not UnitExists(unit..\"target\") or not UnitIsUnit(unit..\"target\", \"player\"))) then\n            if ID and states[ID] then\n                states[ID].show = false;\n                states[ID].changed = true;\n                return true\n            end\n        end\n        \n        if not UnitExists(unit) or UnitPlayerControlled(unit) then return end\n        local DelayedSpell = aura_env.config.spellDelay and (aura_env.config.spellDelay > 0)\n        local castType = UnitCastingInfo(unit) and UnitCastingInfo or UnitChannelInfo\n        local _,displayName,icon,dur,exp,_,int,channelId,castId = castType(unit) -- int = notInterruptible for channel, channelId = notInterruptible for cast\n        \n        local interruptible = UnitCastingInfo(unit) and not channelId or not int\n        local spellId = UnitCastingInfo(unit) and castId or channelId\n        if DelayedSpell and (e == \"UNIT_SPELLCAST_START\" or e == \"UNIT_SPELLCAST_CHANNEL_START\") then\n            C_Timer.After(aura_env.config.spellDelay, function() WeakAuras.ScanEvents(\"UNIT_DELAYED_SPELL_START\", unit) end)\n            if states[ID] then\n                states[ID].show = false;\n                states[ID].changed = true;\n                return true\n            end\n        end\n        \n        if e == \"NAME_PLATE_UNIT_ADDED\" or e == \"UNIT_TARGET\" or \n        (DelayedSpell and (e == \"UNIT_DELAYED_SPELL_START\")) or \n        (not DelayedSpell and (e == \"UNIT_SPELLCAST_START\" or \n        e == \"UNIT_SPELLCAST_CHANNEL_START\")) then\n            if UnitExists(unit..\"target\") and UnitIsUnit(unit..\"target\", \"player\") and \n            (icon and (isBoss) or (not isBoss)) and spellId then\n                states[ID] = states[ID] or {}\n                local state = states[ID]\n                \n                if  aura_env.blacklist[displayName] or aura_env.blacklist[spellId] then return false end\n                \n                state.sayChat = koKR and (C_Spell.GetSpellLink(spellId)..\" 대상\") or (\"Targeted by \"..C_Spell.GetSpellLink(spellId))\n                \n                state.isBoss = isBoss\n                state.interruptible = interruptible\n                state.name = displayName\n                state.spellName = displayName\n                state.spellID = spellId\n                state.icon = icon\n                state.duration = (dur-exp)/1000\n                state.expirationTime = exp/1000\n                state.progressType = \"timed\"\n                state.autohide = true\n                state.show = true\n                state.changed = true\n                return true\n                \n            else\n                if states[ID] then\n                    states[ID].show = false;\n                    states[ID].changed = true;\n                    return true\n                end\n            end\n        end\n    end\nend",
