["custom"] = "aura_env.checkBufferInParty = function(buffer)\n    aura_env.bufferInParty = false\n    \n    for unit in WA_IterateGroupMembers() do\n        if UnitExists(unit) then\n            local _, unitClass, _ = UnitClass(unit)\n            if unitClass == buffer then\n                aura_env.bufferInParty = true\n                return true\n            end\n        end\n    end\n    return false\nend",
