["customText"] = "function()\n    if not aura_env.last or aura_env.last < GetTime() - 0.2 then\n        aura_env.last = GetTime() \n    end\n    \n    local abbr = ''    \n    for i =1, 40 do\n        local _,_,_,_,_,_,_,_,_,spellID,_,_,_,_,_, absb = UnitBuff(\"player\",i)\n        if spellID == 235313 then\n            absb = absb / 1000\n            abbr = string.format(\"%.0fk\", absb)\n        end\n    end\n    \n    return abbr\nend",
